pm.test("Código 403", function () { pm.response.to.have.status(403); });
pm.test("Formato de error común (status y mensaje)", function () {
  var j = pm.response.json();
  pm.expect(j).to.have.property("status");
  pm.expect(j).to.have.property("mensaje");
});

pm.test("200 OK", () => pm.response.to.have.status(200));

const body = pm.response.json();

pm.test("Estructura de la página", () => {
    pm.expect(body).to.have.all.keys("contenido", "pagina", "tamano", "totalElementos", "totalPaginas");
    pm.expect(body.pagina).to.eql(0);
    pm.expect(body.tamano).to.eql(100);
});

pm.test("Solo publicados o agotados con los campos acordados", () => {
    body.contenido.forEach(e => {
        pm.expect(["publicado", "agotado"]).to.include(e.estado);
        pm.expect(e).to.include.keys("eventoId", "nombre", "tipo", "participantes", "ciudad", "fechaHora");
    });
});

